using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpHttpServer;

public class ConfigResources
{
    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    /// <summary>A static resource at a fixed URI returning app configuration.</summary>
    [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings",
        MimeType = "application/json")]
    [Description("Returns the current application configuration")]
    public static ReadResourceResult GetAppSettings(
        RequestContext<ReadResourceRequestParams> context)
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Features = new { EnableCaching = true, MaxConnections = 100 },
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production"
        };

        return new ReadResourceResult
        {
            Contents =
            [
                new TextResourceContents
                {
                    Uri = context.Params!.Uri,
                    MimeType = "application/json",
                    Text = JsonSerializer.Serialize(config, JsonOptions)
                }
            ]
        };
    }

    /// <summary>A resource template with a parameter in the URI.</summary>
    [McpServerResource(UriTemplate = "config://app/features/{featureName}",
        Name = "FeatureFlag", MimeType = "application/json")]
    [Description("Returns the status of a specific feature flag")]
    public static ReadResourceResult GetFeatureFlag(
        RequestContext<ReadResourceRequestParams> context, string featureName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["caching"] = true,
            ["dark-mode"] = false,
            ["beta-api"] = true
        };

        var enabled = flags.TryGetValue(featureName, out var value) && value;

        var result = new { Feature = featureName, Enabled = enabled };

        return new ReadResourceResult
        {
            Contents =
            [
                new TextResourceContents
                {
                    Uri = context.Params!.Uri,
                    MimeType = "application/json",
                    Text = JsonSerializer.Serialize(result, JsonOptions)
                }
            ]
        };
    }
}

